import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uniform, vec3, mix, smoothstep, uv as uvNode, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Vector2, Color } = THREE;

  const group = new Group();
  group.name = 'hub-collection-badge';

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const accent = new Color(colors.accent);
  const paper = new Color(colors.paper);

  // Capsule proportions ~ 1.6 x 0.5
  const W = 1.6;
  const H = 0.5;
  const EDGE = 0.04;

  // --- Accent edge light (slightly larger capsule behind) ---
  const edgeMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0.85,
    side: THREE.DoubleSide,
    depthWrite: false,
  });
  const edgeGeo = new PlaneGeometry(W + EDGE * 2, H + EDGE * 2, 1, 1);
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.z = -0.012;
  group.add(edgeMesh);

  // --- Surface badge plane ---
  const surfMat = new MeshBasicNodeMaterial({
    color: new Color(colors.surface),
    transparent: true,
    opacity: 1.0,
    side: THREE.DoubleSide,
    depthWrite: true,
  });

  // Build a capsule-alpha mask via TSL: rounded rect in uv space.
  const uvn = uvNode.mul(float(1.0));
  const px = uvn.x;
  const py = uvn.y;
  // local centered coords
  const lx = px.sub(float(0.5)).mul(float(W));
  const ly = py.sub(float(0.5)).mul(float(H));
  // rounded rect SDF approximation: clamp distance to rect, smoothstep
  const ax = lx.abs().sub(float(W * 0.5 - EDGE));
  const ay = ly.abs().sub(float(H * 0.5 - EDGE));
  const dx = ax.max(float(0.0));
  const dy = ay.max(float(0.0));
  const outer = dx.mul(dx).add(dy.mul(dy)).sqrt();
  // thickness for ring (accent edge) using distance band
  const distToEdge = outer;
  const ring = smoothstep(float(EDGE), float(0.0), distToEdge);
  // main fill (surface) inside
  const fill = smoothstep(float(EDGE + 0.02), float(EDGE - 0.02), distToEdge).oneMinus();
  // ceramic grain texture load
  const imageUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
    tex.colorSpace = THREE.SRGBColorSpace;
    surfMat.colorNode = null;
    surfMat.map = tex;
    // composite tint: paper surface with subtle accent glow on edge
    const grain = uniform(tex);
    // sample grain (uv default) and tint
    const sampled = mix(uniform(new Color(colors.surface)), uniform(new Color(colors.paper).multiplyScalar(0.85)), smoothstep(float(0.3), float(0.9), grain.x));
    const final = mix(uniform(accent), sampled, fill);
    surfMat.colorNode = final;
    surfMat.opacityNode = fill.max(ring.mul(float(0.9)));
    surfMat.needsUpdate = true;
  });

  // fallback colorNode before texture arrives
  surfMat.colorNode = mix(uniform(accent), uniform(new Color(colors.surface)), fill);
  surfMat.opacityNode = fill;

  const surfGeo = new PlaneGeometry(W, H, 1, 1);
  const surfMesh = new Mesh(surfGeo, surfMat);
  surfMesh.position.z = 0.0;
  group.add(surfMesh);

  // Initial hidden for entrance
  group.position.y = config.scenePosition ? config.scenePosition.y + 0.15 : 1.75;
  group.visible = true;

  // --- Entrance: rise-in ---
  const tlIn = gsap.timeline();
  tlIn.fromTo(group.position, { y: (config.scenePosition?.y ?? 1.6) + 0.15 }, { y: config.scenePosition?.y ?? 1.6, duration: 0.7, ease: 'power3.out' });
  tlIn.fromTo(group.scale, { x: 0.96, y: 0.96, z: 0.96 }, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' }, 0);
  tlIn.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0.5);

  // --- Idle breathing ---
  const tlIdle = gsap.timeline({ repeat: -1, yoyo: true });
  tlIdle.to(group.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 2.4, ease: 'sine.inOut' });

  // hover state
  let hoverLifted = false;
  const hoverTween = { kill: () => {} };

  group.userData.handlers = {
    onpointerenter: () => {
      if (hoverLifted) return;
      hoverLifted = true;
      hoverTween.kill();
      const t = gsap.to(group.position, { y: (config.scenePosition?.y ?? 1.6) + 0.15, duration: 0.4, ease: 'power2.out' });
      hoverTween.kill = () => t.kill();
      gsap.to(edgeMat, { opacity: 1.0, duration: 0.3, ease: 'power2.out' });
    },
    onpointerleave: () => {
      if (!hoverLifted) return;
      hoverLifted = false;
      hoverTween.kill();
      const t = gsap.to(group.position, { y: config.scenePosition?.y ?? 1.6, duration: 0.4, ease: 'power3.out' });
      hoverTween.kill = () => t.kill();
      gsap.to(edgeMat, { opacity: 0.85, duration: 0.3, ease: 'power2.out' });
    },
    onpointerdown: () => {
      gsap.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    },
    onpointerup: () => {
      gsap.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.18, ease: 'power4.out' });
      if (ctx.emit) ctx.emit('navigate', { to: 'hub-collection' });
      ctx.emit('hub-collection.select', {});
    },
  };

  group.userData.cleanup = () => {
    tlIn.kill();
    tlIdle.kill();
    hoverTween.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(edgeMat);
    surfGeo.dispose();
    edgeGeo.dispose();
    surfMat.dispose();
    edgeMat.dispose();
  };

  return group;
}
